        sealed class Rocket {public SourceLaunchDescriptor Launch;public Transform Art;public float Age;public AudioSource Flight,Impact;public bool Exploded;public float Damage;public Vector3 Position;}
        R23Visuals art;R24ItemAudio audio;R23GunFeedback feedback;Transform visual,model,offer,bore,rocketTemplate,worldRockets,arrow;Material plumeMaterial;readonly List<Rocket> rockets=new List<Rocket>();AudioSource launchVoice;bool initialized,equipped,paused,ownsRuntime;float volume=1;IR23ExplosiveEffects effects;Func<Float3> playerHead;int blastSerial;
        public R24SmawRuntime Runtime{get;private set;}public bool Ready{get;private set;}public bool Loading{get;private set;}public string Failure{get;private set;}
        public bool HarmlessPreview{get;set;}public bool Equipped{get{return equipped;}}public int FlyingRockets{get{int n=0;foreach(var r in rockets)if(!r.Exploded)n++;return n;}}
        public string AmmoText{get{return feedback==null?"":feedback.AmmoText;}}public bool AmmoPanelVisible{get{return feedback!=null&&feedback.PanelVisible;}}public bool ReticleVisible{get{return feedback!=null&&feedback.ReticleVisible;}}public bool HeadBlocked{get;private set;}public Vector3 AimPosition{get;private set;}public Vector3 AmmoPanelPosition{get{return feedback==null?Vector3.zero:feedback.PanelPosition;}}public Vector3 ReloadInsertionPosition{get{return model==null?Vector3.zero:model.TransformPoint(V(R24SmawRuntime.Insert));}}
        public bool SharedProjectileAuthority;internal GameObject CreateNetworkRocket(Transform parent){if(!Ready||rocketTemplate==null)return null;var clone=Instantiate(rocketTemplate.gameObject,parent);clone.SetActive(true);return clone;}
        public event Action<SourceLaunchDescriptor> Launched;public event Action<R23GrenadeBlast> Detonated;public event Action Depleted;public event Action<int,float,float> HapticRequested;
        // Optional exclusion must identify actual actor-body colliders. Default map
