        public Func<Collider,bool> IgnoreCollider;public Func<Collider,bool> IgnoreHeadOccluder;
        public void Initialize(string instanceId,int stars,IR23ExplosiveEffects actualEffects,Func<Float3> actualPlayerHead){if(initialized)throw new InvalidOperationException("retain one native SMAW lifetime");ownsRuntime=true;InitializeExisting(new R24SmawRuntime(instanceId,stars),actualEffects,actualPlayerHead);}
        public void InitializeExisting(R24SmawRuntime owner,IR23ExplosiveEffects actualEffects,Func<Float3> actualPlayerHead){if(initialized)throw new InvalidOperationException("SMAW already initialized");if(owner==null)throw new ArgumentNullException("owner");initialized=true;effects=actualEffects;playerHead=actualPlayerHead;Runtime=owner;Loading=true;StartCoroutine(Guard(Load()));}
        public void ConfigureEffects(IR23ExplosiveEffects actualEffects,Func<Float3> actualPlayerHead){effects=actualEffects;playerHead=actualPlayerHead;}
        public void BindOwner(R24SmawRuntime owner){if(owner==null)throw new ArgumentNullException("owner");if(object.ReferenceEquals(Runtime,owner))return;Holster();if(ownsRuntime&&Runtime!=null)Runtime.Retire();Runtime=owner;ownsRuntime=false;}
        public void RefreshTrackedPresentation(R23ShotPose grip,Float3 support,int hand,Camera camera=null){if(!Ready||!equipped||paused||!grip.Valid)return;visual.SetPositionAndRotation(V(grip.Origin),Q(grip));model.localPosition=V(R24SmawRuntime.ModelOffset);model.localRotation=Quaternion.identity;bore.SetPositionAndRotation(model.TransformPoint(V(R24SmawRuntime.SourceMuzzle)),Q(grip));bool reload=Runtime.Loaded==0&&Runtime.Reloads>0;arrow.gameObject.SetActive(false);offer.gameObject.SetActive(reload);if(Runtime.ReloadHandOccupied){offer.SetParent(visual,true);offer.SetPositionAndRotation(V(support),Q(grip));offer.localScale=Vector3.one*R24SmawRuntime.ModelScale;}else{offer.SetParent(model,false);offer.localPosition=V(R24SmawRuntime.Offer);offer.localRotation=Quaternion.identity;offer.localScale=Vector3.one;}feedback.PresentAmmo(model,R24SmawRuntime.ModelScale,Runtime.Loaded,Runtime.Reloads,hand==0,true,.085f,.51f);feedback.PresentFlash(false);if(camera!=null){AimPosition=AimPoint(bore.position,bore.forward);HeadBlocked=!Clear(camera.transform.position,bore.position);feedback.PresentReticle(camera,AimPosition,bore.forward,98f,Runtime.Loaded>0&&!HeadBlocked,false,false,true);}}
        IEnumerator Guard(IEnumerator work){var stack=new Stack<IEnumerator>();stack.Push(work);while(stack.Count>0){object value;try{var top=stack.Peek();if(!top.MoveNext()){stack.Pop();continue;}value=top.Current;}catch(Exception ex){Failure=ex.Message;Loading=false;yield break;}var nested=value as IEnumerator;if(nested!=null)stack.Push(nested);else yield return value;}Loading=false;Ready=true;}
        IEnumerator Load(){worldRockets=new GameObject("R5 independent SMAW projectiles").transform;art=new R23Visuals();audio=new R24ItemAudio();audio.SetVolume(volume);visual=Node("R5 SMAW view",transform);model=Node("source model",visual);model.localScale=Vector3.one*R24SmawRuntime.ModelScale;bore=Node("source muzzle",visual);offer=Node("offered rocket",model);rocketTemplate=Node("source rocket prototype",transform);yield return art.Load("smaw",model);yield return art.Load("smaw-round",offer);yield return art.Load("smaw-round",rocketTemplate);var plume=Node("source unlit plume",rocketTemplate);yield return art.Load("smaw-plume",plume);plumeMaterial=new Material(Resources.Load<Shader>("R23GunFeedback"));plumeMaterial.SetColor("_Color",new Color(1,.851f,.471f));foreach(var renderer in plume.GetComponentsInChildren<Renderer>())renderer.sharedMaterial=plumeMaterial;arrow=Node("source noseward insertion cue",model);arrow.localPosition=new Vector3(.09f,.045f,1.15f);arrow.gameObject.SetActive(false);yield return art.Load("smaw-arrow",arrow);arrow.gameObject.SetActive(false);rocketTemplate.gameObject.SetActive(false);yield return audio.Load("smaw-launch","smaw-flight","smaw-impact");launchVoice=audio.Voice(bore,"source rocket launch -14dB",-14,14);feedback=new R23GunFeedback(visual,bore);visual.gameObject.SetActive(false);art.ReleaseLoadedBytes();}
        static Transform Node(string name,Transform parent){var t=new GameObject(name).transform;t.SetParent(parent,false);return t;}
        static Vector3 V(Float3 a){return new Vector3(a.X,a.Y,a.Z);}static Float3 F(Vector3 a){return new Float3(a.x,a.y,a.z);}static Quaternion Q(R23ShotPose p){return Quaternion.LookRotation(V(p.Forward),V(p.Up));}
        public bool Equip(){if(!Ready||Runtime.Depleted)return false;Runtime.SuspendControls();equipped=true;visual.gameObject.SetActive(!paused);return true;}
        public void Holster(){equipped=false;if(Runtime!=null)Runtime.SuspendControls();if(visual!=null)visual.gameObject.SetActive(false);if(feedback!=null)feedback.Hide();if(launchVoice!=null)launchVoice.Stop();}
        public void SetSfxVolume(float value){volume=Mathf.Clamp01(value);if(audio!=null)audio.SetVolume(volume);}
        public void SetPaused(bool value){paused=value;if(value&&Runtime!=null)Runtime.SuspendControls();if(audio!=null&&value)audio.Stop();foreach(var r in rockets)if(!r.Exploded&&r.Flight!=null){if(value)r.Flight.Pause();else r.Flight.UnPause();}if(visual!=null)visual.gameObject.SetActive(equipped&&!paused);}
        public bool TryReadShotPose(out R23ShotPose shot){shot=new R23ShotPose();if(!Ready||!equipped)return false;shot=new R23ShotPose(F(bore.position),F(bore.right),F(bore.up),F(bore.forward));return true;}
        public bool TryReadPrimaryGloveContact(out R23ShotPose contact){contact=new R23ShotPose();if(!Ready||!equipped)return false;var at=model.TransformPoint(V(R24SmawRuntime.Grip))+visual.TransformDirection(new Vector3(0,.0254f,-.0508f));contact=new R23ShotPose(F(at),F(visual.right),F(visual.up),F(visual.forward));return true;}
        public Vector3 ReloadOfferPosition{get{return offer==null?Vector3.zero:offer.position;}}public bool ReloadHandOccupied{get{return Runtime!=null&&Runtime.ReloadHandOccupied;}}
        public SourceLaunchDescriptor Step(float dt,HandlingInput input,R23ShotPose correctedGrip,Float3 supportWorld,Float3 head,int primaryHand=1,bool desktopReload=false,Camera actualCamera=null,bool advanceProjectiles=true){
            if(!Ready)return null;SetPausedIfChanged(input.Paused);if(advanceProjectiles)AdvanceProjectiles(dt);if(!equipped||!correctedGrip.Valid){Runtime.SuspendControls();return null;}
            visual.SetPositionAndRotation(V(correctedGrip.Origin),Q(correctedGrip));model.localPosition=V(R24SmawRuntime.ModelOffset);model.localRotation=Quaternion.identity;var muzzle=model.TransformPoint(V(R24SmawRuntime.SourceMuzzle));bore.SetPositionAndRotation(muzzle,Q(correctedGrip));
            input.Paused|=paused;input.PrimaryTracked&=correctedGrip.Valid;input.SupportTracked&=supportWorld.IsFinite;input.SupportLocal=supportWorld.IsFinite?F(model.InverseTransformPoint(V(supportWorld))):new Float3();bool clear=head.IsFinite&&Clear(V(head),muzzle);input.HeadObstructed|=!clear;
            var before=Runtime.Snapshot;var descriptor=Runtime.Step(dt,input,new R23ShotPose(F(muzzle),correctedGrip.Right,correctedGrip.Up,correctedGrip.Forward),clear,desktopReload);var after=Runtime.Snapshot;
            arrow.gameObject.SetActive(false);offer.gameObject.SetActive(!paused&&Runtime.Loaded==0&&Runtime.Reloads>0);if(after.HeldRocket){offer.SetParent(visual,true);offer.SetPositionAndRotation(V(supportWorld),Q(correctedGrip));offer.localScale=Vector3.one*R24SmawRuntime.ModelScale;}else{offer.SetParent(model,false);offer.localPosition=V(R24SmawRuntime.Offer);offer.localRotation=Quaternion.identity;offer.localScale=Vector3.one;}
            feedback.PresentAmmo(model,R24SmawRuntime.ModelScale,after.Loaded,after.Reloads,primaryHand==0,!paused&&equipped,.085f,.51f);feedback.PresentFlash(false);if(actualCamera!=null){AimPosition=AimPoint(muzzle,bore.forward);HeadBlocked=!clear;feedback.PresentReticle(actualCamera,AimPosition,bore.forward,98f,!paused&&equipped&&Runtime.Loaded>0&&!HeadBlocked,false,false,true);}
            if(!before.HeldRocket&&after.HeldRocket&&HapticRequested!=null)HapticRequested(1-primaryHand,.34f,.06f);
            if(descriptor!=null){if(!HarmlessPreview&&!SharedProjectileAuthority)Spawn(descriptor);audio.Play(launchVoice,"smaw-launch");if(HapticRequested!=null)HapticRequested(primaryHand,.45f,.06f);if(Launched!=null)Launched(descriptor);if(Runtime.Depleted&&!HarmlessPreview&&!SharedProjectileAuthority){Holster();if(Depleted!=null)Depleted();}}
            return descriptor;
        }
        void SetPausedIfChanged(bool value){if(value!=paused)SetPaused(value);}
        bool Ignored(Collider c){return c==null||c.isTrigger||(IgnoreCollider!=null&&IgnoreCollider(c));}
        Vector3 AimPoint(Vector3 origin,Vector3 direction){float best=SourceRifleDefinition.FirearmRange;Vector3 point=origin+direction*best;foreach(var hit in Physics.RaycastAll(origin,direction,best,(1<<0)|(1<<19),QueryTriggerInteraction.Ignore))if(!Ignored(hit.collider)&&hit.distance<best){best=hit.distance;point=hit.point;}return point;}
        bool Clear(Vector3 start,Vector3 end){var d=end-start;if(d.sqrMagnitude<.000001f)return true;foreach(var hit in Physics.RaycastAll(start,d.normalized,d.magnitude,(1<<0)|(1<<19),QueryTriggerInteraction.Ignore))if(!Ignored(hit.collider)&&(IgnoreHeadOccluder==null||!IgnoreHeadOccluder(hit.collider)))return false;return true;}
        void Spawn(SourceLaunchDescriptor descriptor){var root=Instantiate(rocketTemplate.gameObject).transform;root.name="R5 native rocket "+Runtime.InstanceId;root.SetParent(worldRockets,false);root.SetPositionAndRotation(V(descriptor.Geometry.Origin),Quaternion.LookRotation(V(descriptor.Velocity)));root.localScale=Vector3.one;root.gameObject.SetActive(true);var flight=audio.Voice(root,"source rocket flight",0,60,true);var impact=audio.Voice(root,"source rocket impact -4dB",-4,100);var r=new Rocket{Launch=descriptor,Art=root,Position=root.position,Flight=flight,Impact=impact,Damage=Runtime.Damage};rockets.Add(r);audio.Play(flight,"smaw-flight");}
        public void AdvanceProjectiles(float dt){if(!Ready||paused)return;if(float.IsNaN(dt)||float.IsInfinity(dt)||dt<0||dt>.25f)throw new ArgumentOutOfRangeException("dt");for(int i=rockets.Count-1;i>=0;i--){var r=rockets[i];r.Age+=dt;if(r.Exploded){if(r.Age>=2.5f){Destroy(r.Art.gameObject);rockets.RemoveAt(i);}continue;}bool overlapping=false;foreach(var c in Physics.OverlapSphere(r.Position,R24SmawRuntime.CollisionRadius,(1<<0)|(1<<19),QueryTriggerInteraction.Ignore))if(!Ignored(c)){overlapping=true;break;}if(overlapping){Explode(r);continue;}Vector3 travel=V(r.Launch.Velocity)*dt;RaycastHit? closest=null;if(travel.sqrMagnitude>0)foreach(var hit in Physics.SphereCastAll(r.Position,R24SmawRuntime.CollisionRadius,travel.normalized,travel.magnitude,(1<<0)|(1<<19),QueryTriggerInteraction.Ignore))if(!Ignored(hit.collider)&&(!closest.HasValue||hit.distance<closest.Value.distance))closest=hit;r.Position=closest.HasValue?r.Position+travel.normalized*closest.Value.distance:r.Position+travel;r.Art.position=r.Position;if(closest.HasValue||r.Age>=R24SmawRuntime.ProjectileSeconds)Explode(r);}}
        void Explode(Rocket r){if(r.Exploded)return;r.Exploded=true;r.Age=0;r.Flight.Stop();foreach(var renderer in r.Art.GetComponentsInChildren<Renderer>())renderer.enabled=false;audio.Play(r.Impact,"smaw-impact");var blast=new R23GrenadeBlast(r.Launch.InstanceId,"smaw",++blastSerial,F(r.Position),R24SmawRuntime.Radius,r.Damage,true);if(effects!=null&&playerHead!=null)blast.Apply(effects,playerHead());if(Detonated!=null)Detonated(blast);}
        public void ClearProjectiles(){foreach(var r in rockets)if(r.Art!=null)Destroy(r.Art.gameObject);rockets.Clear();}
        void OnDisable(){Holster();SetPaused(true);}void OnDestroy(){ClearProjectiles();if(ownsRuntime&&Runtime!=null)Runtime.Retire();if(feedback!=null)feedback.Dispose();if(audio!=null)audio.Dispose();if(art!=null)art.Dispose();if(worldRockets!=null)Destroy(worldRockets.gameObject);if(plumeMaterial!=null)Destroy(plumeMaterial);}
